INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (1, 'training', '{"id":1,"phase":"training","category":"account_threat","title":{"en":"Account warning","bn":"অ্যাকাউন্টের সতর্কবার্তা"},"message":{"en":"Update your account now or it will be closed. Use [link removed].","bn":"এখনই অ্যাকাউন্ট আপডেট করুন, না হলে বন্ধ হয়ে যাবে। [লিংক সরানো হয়েছে] ব্যবহার করুন।"},"choices":[{"text":{"en":"Open the official app independently to check.","bn":"নিজে অফিসিয়াল অ্যাপ খুলে যাচাই করি।"},"safe":true,"feedback":{"en":"Safe action. Threats of closure create pressure. Verify independently and never send account details.","bn":"নিরাপদ সিদ্ধান্ত। অ্যাকাউন্ট বন্ধের ভয় দেখিয়ে চাপ দেওয়া হয়। নিজে যাচাই করুন, অ্যাকাউন্টের তথ্য পাঠাবেন না।"},"id":11},{"text":{"en":"Use the message link.","bn":"মেসেজের লিংক ব্যবহার করি।"},"safe":false,"feedback":{"en":"Not the safest action. Threats of closure create pressure. Verify independently and never send account details.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অ্যাকাউন্ট বন্ধের ভয় দেখিয়ে চাপ দেওয়া হয়। নিজে যাচাই করুন, অ্যাকাউন্টের তথ্য পাঠাবেন না।"},"id":12},{"text":{"en":"Send account details in reply.","bn":"উত্তরে অ্যাকাউন্টের তথ্য পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. Threats of closure create pressure. Verify independently and never send account details.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অ্যাকাউন্ট বন্ধের ভয় দেখিয়ে চাপ দেওয়া হয়। নিজে যাচাই করুন, অ্যাকাউন্টের তথ্য পাঠাবেন না।"},"id":13}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 117; Bengali","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (2, 'training', '{"id":2,"phase":"training","category":"mobile_verification","title":{"en":"Mobile verification","bn":"মোবাইল নম্বর যাচাই"},"message":{"en":"Verify your mobile number using [link removed].","bn":"মোবাইল নম্বর যাচাই করতে [লিংক সরানো হয়েছে] ব্যবহার করুন।"},"choices":[{"text":{"en":"Enter my details through the link.","bn":"লিংকে নিজের তথ্য দিই।"},"safe":false,"feedback":{"en":"Not the safest action. Unrequested verification links may steal information. Use official channels and keep codes private.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অপ্রত্যাশিত যাচাই লিংক তথ্য চুরি করতে পারে। অফিসিয়াল মাধ্যম ব্যবহার করুন ও কোড গোপন রাখুন।"},"id":21},{"text":{"en":"Forward my verification code.","bn":"যাচাই কোড পাঠিয়ে দিই।"},"safe":false,"feedback":{"en":"Not the safest action. Unrequested verification links may steal information. Use official channels and keep codes private.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অপ্রত্যাশিত যাচাই লিংক তথ্য চুরি করতে পারে। অফিসিয়াল মাধ্যম ব্যবহার করুন ও কোড গোপন রাখুন।"},"id":22},{"text":{"en":"Check with the mobile operator through its official app.","bn":"অপারেটরের অফিসিয়াল অ্যাপে যাচাই করি।"},"safe":true,"feedback":{"en":"Safe action. Unrequested verification links may steal information. Use official channels and keep codes private.","bn":"নিরাপদ সিদ্ধান্ত। অপ্রত্যাশিত যাচাই লিংক তথ্য চুরি করতে পারে। অফিসিয়াল মাধ্যম ব্যবহার করুন ও কোড গোপন রাখুন।"},"id":23}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 123; Bengali","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (3, 'training', '{"id":3,"phase":"training","category":"prize","title":{"en":"Unexpected prize","bn":"অপ্রত্যাশিত পুরস্কার"},"message":{"en":"Call [number removed] to collect your prize money.","bn":"পুরস্কারের টাকা পেতে [নম্বর সরানো হয়েছে] নম্বরে কল করুন।"},"choices":[{"text":{"en":"Send my payment details to claim it.","bn":"পুরস্কার পেতে লেনদেনের তথ্য পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. Unexpected prizes can be bait for fees or personal data. Do not use contact details from the message.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অপ্রত্যাশিত পুরস্কার ফি বা ব্যক্তিগত তথ্য নেওয়ার ফাঁদ হতে পারে। মেসেজের যোগাযোগের তথ্য ব্যবহার করবেন না।"},"id":31},{"text":{"en":"Do not contact the supplied number; verify the prize independently.","bn":"দেওয়া নম্বরে কল না করে নিজে পুরস্কারের সত্যতা যাচাই করি।"},"safe":true,"feedback":{"en":"Safe action. Unexpected prizes can be bait for fees or personal data. Do not use contact details from the message.","bn":"নিরাপদ সিদ্ধান্ত। অপ্রত্যাশিত পুরস্কার ফি বা ব্যক্তিগত তথ্য নেওয়ার ফাঁদ হতে পারে। মেসেজের যোগাযোগের তথ্য ব্যবহার করবেন না।"},"id":32},{"text":{"en":"Call the number immediately.","bn":"এখনই ওই নম্বরে কল করি।"},"safe":false,"feedback":{"en":"Not the safest action. Unexpected prizes can be bait for fees or personal data. Do not use contact details from the message.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অপ্রত্যাশিত পুরস্কার ফি বা ব্যক্তিগত তথ্য নেওয়ার ফাঁদ হতে পারে। মেসেজের যোগাযোগের তথ্য ব্যবহার করবেন না।"},"id":33}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 132; Bengali","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (4, 'training', '{"id":4,"phase":"training","category":"online_shopping","title":{"en":"Gift voucher","bn":"উপহারের ভাউচার"},"message":{"en":"A shopping voucher is waiting. Claim it at [link removed].","bn":"আপনার জন্য কেনাকাটার ভাউচার আছে। [লিংক সরানো হয়েছে] থেকে নিন।"},"choices":[{"text":{"en":"Check offers inside the official shopping app.","bn":"অফিসিয়াল কেনাকাটার অ্যাপে অফার যাচাই করি।"},"safe":true,"feedback":{"en":"Safe action. Fake vouchers imitate familiar shops. Use the official app instead of unfamiliar links.","bn":"নিরাপদ সিদ্ধান্ত। ভুয়া ভাউচার পরিচিত দোকানের নাম ব্যবহার করতে পারে। অপরিচিত লিংকের বদলে অফিসিয়াল অ্যাপ ব্যবহার করুন।"},"id":41},{"text":{"en":"Sign in through the message link.","bn":"মেসেজের লিংকে লগইন করি।"},"safe":false,"feedback":{"en":"Not the safest action. Fake vouchers imitate familiar shops. Use the official app instead of unfamiliar links.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। ভুয়া ভাউচার পরিচিত দোকানের নাম ব্যবহার করতে পারে। অপরিচিত লিংকের বদলে অফিসিয়াল অ্যাপ ব্যবহার করুন।"},"id":42},{"text":{"en":"Give my card details to claim it.","bn":"ভাউচার পেতে কার্ডের তথ্য দিই।"},"safe":false,"feedback":{"en":"Not the safest action. Fake vouchers imitate familiar shops. Use the official app instead of unfamiliar links.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। ভুয়া ভাউচার পরিচিত দোকানের নাম ব্যবহার করতে পারে। অপরিচিত লিংকের বদলে অফিসিয়াল অ্যাপ ব্যবহার করুন।"},"id":43}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 140; Bengali","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (5, 'training', '{"id":5,"phase":"training","category":"cashback","title":{"en":"Holiday bonus","bn":"উৎসবের বোনাস"},"message":{"en":"A bank is offering a holiday bonus to mobile-wallet users. Submit your mobile-wallet number at [link removed].","bn":"একটি ব্যাংক উৎসব উপলক্ষে মোবাইল ওয়ালেট ব্যবহারকারীদের বোনাস দিচ্ছে। [লিংক সরানো হয়েছে] থেকে নম্বর দিন।"},"choices":[{"text":{"en":"Enter my number through the link.","bn":"লিংকে নম্বর দিই।"},"safe":false,"feedback":{"en":"Not the safest action. A familiar bank name does not prove an offer is genuine. Check the official app before sharing any information.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। পরিচিত ব্যাংকের নাম থাকলেই অফার সত্য হয় না। তথ্য দেওয়ার আগে অফিসিয়াল অ্যাপে যাচাই করুন।"},"id":51},{"text":{"en":"Share the message with friends as confirmed.","bn":"সত্য ধরে বন্ধুদের কাছে পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. A familiar bank name does not prove an offer is genuine. Check the official app before sharing any information.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। পরিচিত ব্যাংকের নাম থাকলেই অফার সত্য হয় না। তথ্য দেওয়ার আগে অফিসিয়াল অ্যাপে যাচাই করুন।"},"id":52},{"text":{"en":"Check the offer in the official wallet app.","bn":"ওয়ালেটের অফিসিয়াল অ্যাপে অফার যাচাই করি।"},"safe":true,"feedback":{"en":"Safe action. A familiar bank name does not prove an offer is genuine. Check the official app before sharing any information.","bn":"নিরাপদ সিদ্ধান্ত। পরিচিত ব্যাংকের নাম থাকলেই অফার সত্য হয় না। তথ্য দেওয়ার আগে অফিসিয়াল অ্যাপে যাচাই করুন।"},"id":53}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 145; Bengali","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (6, 'training', '{"id":6,"phase":"training","category":"bank_impersonation","title":{"en":"Bank account problem","bn":"ব্যাংক অ্যাকাউন্টে সমস্যা"},"message":{"en":"There is a problem with your bank account. Contact [number removed].","bn":"আপনার ব্যাংক অ্যাকাউন্টে সমস্যা হয়েছে। [নম্বর সরানো হয়েছে] নম্বরে যোগাযোগ করুন।"},"choices":[{"text":{"en":"Send my banking password.","bn":"ব্যাংকিং পাসওয়ার্ড পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. A sender can impersonate a bank. Use contact information you already trust; never share passwords.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। প্রেরক ব্যাংকের পরিচয় নকল করতে পারে। পরিচিত নির্ভরযোগ্য নম্বর ব্যবহার করুন, পাসওয়ার্ড দেবেন না।"},"id":61},{"text":{"en":"Call the number printed on my bank card or official website.","bn":"ব্যাংক কার্ড বা অফিসিয়াল ওয়েবসাইটের নম্বরে কল করি।"},"safe":true,"feedback":{"en":"Safe action. A sender can impersonate a bank. Use contact information you already trust; never share passwords.","bn":"নিরাপদ সিদ্ধান্ত। প্রেরক ব্যাংকের পরিচয় নকল করতে পারে। পরিচিত নির্ভরযোগ্য নম্বর ব্যবহার করুন, পাসওয়ার্ড দেবেন না।"},"id":62},{"text":{"en":"Call the number in the message.","bn":"মেসেজের নম্বরে কল করি।"},"safe":false,"feedback":{"en":"Not the safest action. A sender can impersonate a bank. Use contact information you already trust; never share passwords.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। প্রেরক ব্যাংকের পরিচয় নকল করতে পারে। পরিচিত নির্ভরযোগ্য নম্বর ব্যবহার করুন, পাসওয়ার্ড দেবেন না।"},"id":63}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 181; English","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (7, 'training', '{"id":7,"phase":"training","category":"wallet_problem","title":{"en":"Mobile wallet problem","bn":"মোবাইল ওয়ালেটে সমস্যা"},"message":{"en":"Your mobile-wallet account has an error. Call [number removed].","bn":"আপনার মোবাইল ওয়ালেট অ্যাকাউন্টে ত্রুটি দেখা দিয়েছে। [নম্বর সরানো হয়েছে] নম্বরে কল করুন।"},"choices":[{"text":{"en":"Check the wallet using its official app or support.","bn":"ওয়ালেটের অফিসিয়াল অ্যাপ বা সহায়তা কেন্দ্রে যাচাই করি।"},"safe":true,"feedback":{"en":"Safe action. Fake support can request your PIN or OTP. Never disclose them, even to someone claiming to be support.","bn":"নিরাপদ সিদ্ধান্ত। ভুয়া সহায়তাকারী পিন বা ওটিপি চাইতে পারে। সহায়তাকারী দাবি করলেও এসব দেবেন না।"},"id":71},{"text":{"en":"Call the number from the message.","bn":"মেসেজের নম্বরে কল করি।"},"safe":false,"feedback":{"en":"Not the safest action. Fake support can request your PIN or OTP. Never disclose them, even to someone claiming to be support.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। ভুয়া সহায়তাকারী পিন বা ওটিপি চাইতে পারে। সহায়তাকারী দাবি করলেও এসব দেবেন না।"},"id":72},{"text":{"en":"Share my wallet PIN if requested.","bn":"চাইলে ওয়ালেটের পিন দিই।"},"safe":false,"feedback":{"en":"Not the safest action. Fake support can request your PIN or OTP. Never disclose them, even to someone claiming to be support.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। ভুয়া সহায়তাকারী পিন বা ওটিপি চাইতে পারে। সহায়তাকারী দাবি করলেও এসব দেবেন না।"},"id":73}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 161; Bengali","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (8, 'training', '{"id":8,"phase":"training","category":"job_offer","title":{"en":"Easy income offer","bn":"সহজ আয়ের অফার"},"message":{"en":"Earn money every day by joining through [link removed].","bn":"[লিংক সরানো হয়েছে] দিয়ে যোগ দিয়ে প্রতিদিন টাকা আয় করুন।"},"choices":[{"text":{"en":"Join through the link immediately.","bn":"এখনই লিংক দিয়ে যোগ দিই।"},"safe":false,"feedback":{"en":"Not the safest action. Promises of easy money may lead to fraudulent jobs or advance fees. Verify the employer and avoid paying to unlock work.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। সহজ আয়ের প্রতিশ্রুতি ভুয়া চাকরি বা অগ্রিম ফি নেওয়ার ফাঁদ হতে পারে। প্রতিষ্ঠান যাচাই করুন, কাজ পাওয়ার জন্য টাকা দেবেন না।"},"id":81},{"text":{"en":"Send money if asked to activate the job.","bn":"কাজ চালু করতে চাইলে টাকা পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. Promises of easy money may lead to fraudulent jobs or advance fees. Verify the employer and avoid paying to unlock work.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। সহজ আয়ের প্রতিশ্রুতি ভুয়া চাকরি বা অগ্রিম ফি নেওয়ার ফাঁদ হতে পারে। প্রতিষ্ঠান যাচাই করুন, কাজ পাওয়ার জন্য টাকা দেবেন না।"},"id":82},{"text":{"en":"Research the company independently before joining.","bn":"যোগ দেওয়ার আগে নিজে প্রতিষ্ঠান সম্পর্কে যাচাই করি।"},"safe":true,"feedback":{"en":"Safe action. Promises of easy money may lead to fraudulent jobs or advance fees. Verify the employer and avoid paying to unlock work.","bn":"নিরাপদ সিদ্ধান্ত। সহজ আয়ের প্রতিশ্রুতি ভুয়া চাকরি বা অগ্রিম ফি নেওয়ার ফাঁদ হতে পারে। প্রতিষ্ঠান যাচাই করুন, কাজ পাওয়ার জন্য টাকা দেবেন না।"},"id":83}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 135; English","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (9, 'training', '{"id":9,"phase":"training","category":"family_emergency","title":{"en":"Family emergency","bn":"পরিবারের জরুরি খবর"},"message":{"en":"Your son is in trouble. Pay money immediately using [link removed].","bn":"আপনার ছেলে বিপদে পড়েছে। এখনই [লিংক সরানো হয়েছে] দিয়ে টাকা পাঠান।"},"choices":[{"text":{"en":"Give the sender my banking details.","bn":"প্রেরককে ব্যাংকিং তথ্য দিই।"},"safe":false,"feedback":{"en":"Not the safest action. Fraudsters use fear and urgency. Contact your family through a known number before paying.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। প্রতারকেরা ভয় ও তাড়াহুড়া কাজে লাগায়। টাকা দেওয়ার আগে পরিচিত নম্বরে পরিবারের সঙ্গে কথা বলুন।"},"id":91},{"text":{"en":"Call my son or another trusted family member directly.","bn":"ছেলে বা পরিচিত পরিবারের সদস্যকে সরাসরি কল করি।"},"safe":true,"feedback":{"en":"Safe action. Fraudsters use fear and urgency. Contact your family through a known number before paying.","bn":"নিরাপদ সিদ্ধান্ত। প্রতারকেরা ভয় ও তাড়াহুড়া কাজে লাগায়। টাকা দেওয়ার আগে পরিচিত নম্বরে পরিবারের সঙ্গে কথা বলুন।"},"id":92},{"text":{"en":"Send money immediately through the link.","bn":"লিংক দিয়ে এখনই টাকা পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. Fraudsters use fear and urgency. Contact your family through a known number before paying.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। প্রতারকেরা ভয় ও তাড়াহুড়া কাজে লাগায়। টাকা দেওয়ার আগে পরিচিত নম্বরে পরিবারের সঙ্গে কথা বলুন।"},"id":93}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 176; English","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (10, 'training', '{"id":10,"phase":"training","category":"delivery","title":{"en":"Parcel on hold","bn":"পার্সেল আটকে আছে"},"message":{"en":"Your parcel is on hold. Provide more information using [link removed].","bn":"আপনার পার্সেল আটকে আছে। [লিংক সরানো হয়েছে] দিয়ে আরও তথ্য দিন।"},"choices":[{"text":{"en":"Check my order through the courier’s official service.","bn":"কুরিয়ারের অফিসিয়াল মাধ্যমে অর্ডার যাচাই করি।"},"safe":true,"feedback":{"en":"Safe action. Delivery scams exploit expected parcels. Use the original order confirmation or official courier tracking.","bn":"নিরাপদ সিদ্ধান্ত। পার্সেল আসার অপেক্ষাকে প্রতারকেরা কাজে লাগায়। আসল অর্ডার তথ্য বা অফিসিয়াল ট্র্যাকিং ব্যবহার করুন।"},"id":101},{"text":{"en":"Enter my personal details through the link.","bn":"লিংকে ব্যক্তিগত তথ্য দিই।"},"safe":false,"feedback":{"en":"Not the safest action. Delivery scams exploit expected parcels. Use the original order confirmation or official courier tracking.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। পার্সেল আসার অপেক্ষাকে প্রতারকেরা কাজে লাগায়। আসল অর্ডার তথ্য বা অফিসিয়াল ট্র্যাকিং ব্যবহার করুন।"},"id":102},{"text":{"en":"Pay an unexpected fee through the link.","bn":"লিংক দিয়ে অপ্রত্যাশিত ফি দিই।"},"safe":false,"feedback":{"en":"Not the safest action. Delivery scams exploit expected parcels. Use the original order confirmation or official courier tracking.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। পার্সেল আসার অপেক্ষাকে প্রতারকেরা কাজে লাগায়। আসল অর্ডার তথ্য বা অফিসিয়াল ট্র্যাকিং ব্যবহার করুন।"},"id":103}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 182; CodeMix","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (11, 'training', '{"id":11,"phase":"training","category":"lottery","title":{"en":"Lottery notification","bn":"লটারির খবর"},"message":{"en":"You have won a large lottery prize. Contact [number removed] to claim it.","bn":"আপনি বড় লটারি পুরস্কার জিতেছেন। নিতে [নম্বর সরানো হয়েছে] নম্বরে যোগাযোগ করুন।"},"choices":[{"text":{"en":"Contact the sender and pay a claim fee.","bn":"প্রেরকের সঙ্গে যোগাযোগ করে ফি দিই।"},"safe":false,"feedback":{"en":"Not the safest action. A surprise lottery is not proof of a win. Do not pay fees or send identity documents.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অপ্রত্যাশিত লটারির বার্তা জয়ের প্রমাণ নয়। ফি বা পরিচয়পত্র দেবেন না।"},"id":111},{"text":{"en":"Send my identity documents.","bn":"পরিচয়পত্র পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. A surprise lottery is not proof of a win. Do not pay fees or send identity documents.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অপ্রত্যাশিত লটারির বার্তা জয়ের প্রমাণ নয়। ফি বা পরিচয়পত্র দেবেন না।"},"id":112},{"text":{"en":"Do not pay or provide information; verify independently.","bn":"টাকা বা তথ্য না দিয়ে নিজে যাচাই করি।"},"safe":true,"feedback":{"en":"Safe action. A surprise lottery is not proof of a win. Do not pay fees or send identity documents.","bn":"নিরাপদ সিদ্ধান্ত। অপ্রত্যাশিত লটারির বার্তা জয়ের প্রমাণ নয়। ফি বা পরিচয়পত্র দেবেন না।"},"id":113}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"smish","locator":"preview line 166; English","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (12, 'training', '{"id":12,"phase":"training","category":"subscription","title":{"en":"Phone reward","bn":"ফোনের পুরস্কার"},"message":{"en":"A message claims you can receive free talk time by texting a supplied number. [Number removed.]","bn":"একটি মেসেজে বলা হয়েছে, দেওয়া নম্বরে এসএমএস পাঠালে বিনা মূল্যে কথা বলার সময় পাবেন। [নম্বর সরানো হয়েছে]"},"choices":[{"text":{"en":"Give the sender my verification code.","bn":"প্রেরককে যাচাই কোড দিই।"},"safe":false,"feedback":{"en":"Not the safest action. Unsolicited rewards can involve paid subscriptions. Verify terms through your operator.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অপ্রত্যাশিত পুরস্কারে টাকা কাটা সাবস্ক্রিপশন থাকতে পারে। অপারেটরের মাধ্যমে শর্ত যাচাই করুন।"},"id":121},{"text":{"en":"Check the offer in the operator’s official app.","bn":"অপারেটরের অফিসিয়াল অ্যাপে অফার দেখি।"},"safe":true,"feedback":{"en":"Safe action. Unsolicited rewards can involve paid subscriptions. Verify terms through your operator.","bn":"নিরাপদ সিদ্ধান্ত। অপ্রত্যাশিত পুরস্কারে টাকা কাটা সাবস্ক্রিপশন থাকতে পারে। অপারেটরের মাধ্যমে শর্ত যাচাই করুন।"},"id":122},{"text":{"en":"Text the supplied number without checking.","bn":"যাচাই না করে ওই নম্বরে এসএমএস পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. Unsolicited rewards can involve paid subscriptions. Verify terms through your operator.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। অপ্রত্যাশিত পুরস্কারে টাকা কাটা সাবস্ক্রিপশন থাকতে পারে। অপারেটরের মাধ্যমে শর্ত যাচাই করুন।"},"id":123}],"source":{"type":"dataset_preview_adaptation","dataset":"UCI SMS Spam Collection","url":"https://archive.ics.uci.edu/dataset/228/sms","original_label":"spam","locator":"public examples, free talk-time reward; English","provenance_note":"Paraphrase of public example; spam label is not proof of phishing"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (13, 'training', '{"id":13,"phase":"training","category":"benign","title":{"en":"Family message","bn":"পরিবারের মেসেজ"},"message":{"en":"My exam results will be published tomorrow. Please pray for me.","bn":"আমার পরীক্ষার ফল কাল বের হবে। দোয়া করবেন।"},"choices":[{"text":{"en":"Reply normally if I know the sender.","bn":"প্রেরককে চিনলে স্বাভাবিকভাবে উত্তর দিই।"},"safe":true,"feedback":{"en":"Safe action. An expected family message without a sensitive request can be ordinary communication. Never send secrets.","bn":"নিরাপদ সিদ্ধান্ত। পরিচিত পরিবারের প্রত্যাশিত মেসেজে গোপন তথ্য না চাইলে তা সাধারণ যোগাযোগ হতে পারে। গোপন তথ্য দেবেন না।"},"id":131},{"text":{"en":"Send my bank PIN as a reply.","bn":"উত্তরে ব্যাংকের পিন পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. An expected family message without a sensitive request can be ordinary communication. Never send secrets.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। পরিচিত পরিবারের প্রত্যাশিত মেসেজে গোপন তথ্য না চাইলে তা সাধারণ যোগাযোগ হতে পারে। গোপন তথ্য দেবেন না।"},"id":132},{"text":{"en":"Report it as fraud solely because it is a message.","bn":"শুধু মেসেজ বলে প্রতারণা হিসেবে রিপোর্ট করি।"},"safe":false,"feedback":{"en":"Not the safest action. An expected family message without a sensitive request can be ordinary communication. Never send secrets.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। পরিচিত পরিবারের প্রত্যাশিত মেসেজে গোপন তথ্য না চাইলে তা সাধারণ যোগাযোগ হতে পারে। গোপন তথ্য দেবেন না।"},"id":133}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"normal","locator":"preview line 142; Bengali","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (14, 'training', '{"id":14,"phase":"training","category":"benign","title":{"en":"Shopping conversation","bn":"কেনাকাটার কথা"},"message":{"en":"Are you going to the shopping mall?","bn":"আপনি কি শপিং মলে যাচ্ছেন?"},"choices":[{"text":{"en":"Send my bank account password.","bn":"ব্যাংক অ্যাকাউন্টের পাসওয়ার্ড পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. A simple question with no payment or credential request is not automatically suspicious. Consider who sent it.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। টাকা বা গোপন তথ্য না চাওয়া সাধারণ প্রশ্ন নিজে থেকেই সন্দেহজনক নয়। প্রেরক কে তা বিবেচনা করুন।"},"id":141},{"text":{"en":"Block every message containing a shopping question.","bn":"কেনাকাটার প্রশ্ন থাকা সব মেসেজ ব্লক করি।"},"safe":false,"feedback":{"en":"Not the safest action. A simple question with no payment or credential request is not automatically suspicious. Consider who sent it.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। টাকা বা গোপন তথ্য না চাওয়া সাধারণ প্রশ্ন নিজে থেকেই সন্দেহজনক নয়। প্রেরক কে তা বিবেচনা করুন।"},"id":142},{"text":{"en":"Reply normally if I recognize the sender.","bn":"প্রেরক পরিচিত হলে স্বাভাবিকভাবে উত্তর দিই।"},"safe":true,"feedback":{"en":"Safe action. A simple question with no payment or credential request is not automatically suspicious. Consider who sent it.","bn":"নিরাপদ সিদ্ধান্ত। টাকা বা গোপন তথ্য না চাওয়া সাধারণ প্রশ্ন নিজে থেকেই সন্দেহজনক নয়। প্রেরক কে তা বিবেচনা করুন।"},"id":143}],"source":{"type":"dataset_preview_adaptation","dataset":"Bengali SMS Smishing Dataset","url":"https://huggingface.co/datasets/sujonsamir/bengali-sms-smishing-dataset","original_label":"normal","locator":"preview line 130; English","provenance_note":"Adapted/paraphrased; identifiers removed; original collection method not independently verified"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (15, 'training', '{"id":15,"phase":"training","category":"benign","title":{"en":"Appointment reminder","bn":"অ্যাপয়েন্টমেন্টের স্মরণবার্তা"},"message":{"en":"Your previously booked clinic appointment is tomorrow at 10 AM. No reply required.","bn":"আপনার আগে ঠিক করা ক্লিনিকের অ্যাপয়েন্টমেন্ট কাল সকাল ১০টায়। উত্তর দেওয়ার দরকার নেই।"},"choices":[{"text":{"en":"Assume every appointment reminder is fraud.","bn":"সব অ্যাপয়েন্টমেন্টের স্মরণবার্তা প্রতারণা ধরে নিই।"},"safe":false,"feedback":{"en":"Not the safest action. An expected reminder without a request for money or secrets can be useful. Verify with known contacts if uncertain.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। টাকা বা গোপন তথ্য না চাওয়া প্রত্যাশিত স্মরণবার্তা কাজে লাগতে পারে। সন্দেহ হলে পরিচিত নম্বরে যাচাই করুন।"},"id":151},{"text":{"en":"Keep the reminder; call the clinic’s known number if unsure.","bn":"স্মরণবার্তা রাখি; সন্দেহ হলে ক্লিনিকের পরিচিত নম্বরে কল করি।"},"safe":true,"feedback":{"en":"Safe action. An expected reminder without a request for money or secrets can be useful. Verify with known contacts if uncertain.","bn":"নিরাপদ সিদ্ধান্ত। টাকা বা গোপন তথ্য না চাওয়া প্রত্যাশিত স্মরণবার্তা কাজে লাগতে পারে। সন্দেহ হলে পরিচিত নম্বরে যাচাই করুন।"},"id":152},{"text":{"en":"Send my OTP to confirm the appointment.","bn":"অ্যাপয়েন্টমেন্ট নিশ্চিত করতে ওটিপি পাঠাই।"},"safe":false,"feedback":{"en":"Not the safest action. An expected reminder without a request for money or secrets can be useful. Verify with known contacts if uncertain.","bn":"এটি সবচেয়ে নিরাপদ সিদ্ধান্ত নয়। টাকা বা গোপন তথ্য না চাওয়া প্রত্যাশিত স্মরণবার্তা কাজে লাগতে পারে। সন্দেহ হলে পরিচিত নম্বরে যাচাই করুন।"},"id":153}],"source":{"type":"author_created","dataset":null,"url":null,"original_label":"normal","locator":"author-created control","provenance_note":"Synthetic educational control"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (101, 'pre', '{"id":101,"phase":"pre","category":"suspicious","title":{"en":"OTP request","bn":"ওটিপি চাওয়া"},"message":{"en":"An unexpected caller says your wallet needs an OTP to stay active.","bn":"অপরিচিত কলার বলছে ওয়ালেট সচল রাখতে ওটিপি দিতে হবে।"},"choices":[{"text":{"en":"Text the OTP to the caller.","bn":"কলারকে ওটিপি পাঠাই।"},"safe":false,"feedback":{"en":"OTP codes must remain private.","bn":"ওটিপি গোপন রাখতে হবে।"},"id":1011},{"text":{"en":"Refuse and check official support.","bn":"না বলে অফিসিয়াল সহায়তায় যাচাই করি।"},"safe":true,"feedback":{"en":"OTP codes must remain private.","bn":"ওটিপি গোপন রাখতে হবে।"},"id":1012},{"text":{"en":"Read the OTP to the caller.","bn":"কলারকে ওটিপি বলি।"},"safe":false,"feedback":{"en":"OTP codes must remain private.","bn":"ওটিপি গোপন রাখতে হবে।"},"id":1013}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (102, 'pre', '{"id":102,"phase":"pre","category":"suspicious","title":{"en":"Prize fee","bn":"পুরস্কারের ফি"},"message":{"en":"A message says you won a phone and must pay a delivery fee to claim it.","bn":"মেসেজে বলা হয়েছে ফোন জিতেছেন, নিতে ডেলিভারি ফি দিতে হবে।"},"choices":[{"text":{"en":"Verify the contest independently without paying.","bn":"টাকা না দিয়ে নিজে প্রতিযোগিতা যাচাই করি।"},"safe":true,"feedback":{"en":"Unexpected prizes and advance fees are warning signs.","bn":"অপ্রত্যাশিত পুরস্কার ও অগ্রিম ফি সতর্কতার লক্ষণ।"},"id":1021},{"text":{"en":"Pay the fee now.","bn":"এখনই ফি দিই।"},"safe":false,"feedback":{"en":"Unexpected prizes and advance fees are warning signs.","bn":"অপ্রত্যাশিত পুরস্কার ও অগ্রিম ফি সতর্কতার লক্ষণ।"},"id":1022},{"text":{"en":"Send identity documents.","bn":"পরিচয়পত্র পাঠাই।"},"safe":false,"feedback":{"en":"Unexpected prizes and advance fees are warning signs.","bn":"অপ্রত্যাশিত পুরস্কার ও অগ্রিম ফি সতর্কতার লক্ষণ।"},"id":1023}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (103, 'pre', '{"id":103,"phase":"pre","category":"suspicious","title":{"en":"Account link","bn":"অ্যাকাউন্টের লিংক"},"message":{"en":"An unexpected message says your email account will close unless you sign in through its link.","bn":"অপ্রত্যাশিত মেসেজে বলা হয়েছে লিংকে লগইন না করলে ইমেইল বন্ধ হবে।"},"choices":[{"text":{"en":"Use the supplied link.","bn":"দেওয়া লিংক ব্যবহার করি।"},"safe":false,"feedback":{"en":"Use the official service rather than an unexpected link.","bn":"অপ্রত্যাশিত লিংকের বদলে অফিসিয়াল সেবা ব্যবহার করুন।"},"id":1031},{"text":{"en":"Reply with my password.","bn":"উত্তরে পাসওয়ার্ড দিই।"},"safe":false,"feedback":{"en":"Use the official service rather than an unexpected link.","bn":"অপ্রত্যাশিত লিংকের বদলে অফিসিয়াল সেবা ব্যবহার করুন।"},"id":1032},{"text":{"en":"Open my email service directly.","bn":"নিজে ইমেইল সেবা খুলি।"},"safe":true,"feedback":{"en":"Use the official service rather than an unexpected link.","bn":"অপ্রত্যাশিত লিংকের বদলে অফিসিয়াল সেবা ব্যবহার করুন।"},"id":1033}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (104, 'pre', '{"id":104,"phase":"pre","category":"benign","title":{"en":"Expected message","bn":"প্রত্যাশিত মেসেজ"},"message":{"en":"Your known neighbor confirms the meeting you arranged for tomorrow.","bn":"পরিচিত প্রতিবেশী কালকের ঠিক করা দেখা করার কথা নিশ্চিত করেছেন।"},"choices":[{"text":{"en":"Report it solely because it is a text.","bn":"শুধু মেসেজ বলে রিপোর্ট করি।"},"safe":false,"feedback":{"en":"Expected messages without sensitive requests need not be treated as scams.","bn":"গোপন তথ্য না চাওয়া প্রত্যাশিত মেসেজকে প্রতারণা ভাবার দরকার নেই।"},"id":1041},{"text":{"en":"Reply normally.","bn":"স্বাভাবিকভাবে উত্তর দিই।"},"safe":true,"feedback":{"en":"Expected messages without sensitive requests need not be treated as scams.","bn":"গোপন তথ্য না চাওয়া প্রত্যাশিত মেসেজকে প্রতারণা ভাবার দরকার নেই।"},"id":1042},{"text":{"en":"Send my PIN to confirm.","bn":"নিশ্চিত করতে পিন দিই।"},"safe":false,"feedback":{"en":"Expected messages without sensitive requests need not be treated as scams.","bn":"গোপন তথ্য না চাওয়া প্রত্যাশিত মেসেজকে প্রতারণা ভাবার দরকার নেই।"},"id":1043}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (105, 'pre', '{"id":105,"phase":"pre","category":"suspicious","title":{"en":"Unexpected transfer","bn":"অপ্রত্যাশিত টাকা পাঠানোর অনুরোধ"},"message":{"en":"An unknown number claims to be your nephew and urgently asks for money.","bn":"অপরিচিত নম্বর থেকে ভাগনে পরিচয় দিয়ে জরুরি টাকা চাওয়া হচ্ছে।"},"choices":[{"text":{"en":"Call my nephew on his known number.","bn":"ভাগনের পরিচিত নম্বরে কল করি।"},"safe":true,"feedback":{"en":"Verify family requests through a trusted number.","bn":"পরিচিত নম্বরে পরিবারের অনুরোধ যাচাই করুন।"},"id":1051},{"text":{"en":"Transfer money now.","bn":"এখনই টাকা পাঠাই।"},"safe":false,"feedback":{"en":"Verify family requests through a trusted number.","bn":"পরিচিত নম্বরে পরিবারের অনুরোধ যাচাই করুন।"},"id":1052},{"text":{"en":"Send bank details.","bn":"ব্যাংকের তথ্য পাঠাই।"},"safe":false,"feedback":{"en":"Verify family requests through a trusted number.","bn":"পরিচিত নম্বরে পরিবারের অনুরোধ যাচাই করুন।"},"id":1053}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (106, 'post', '{"id":106,"phase":"post","category":"suspicious","title":{"en":"Verification code","bn":"যাচাই কোড"},"message":{"en":"A caller claiming to be from your bank asks for the verification code sent to your phone.","bn":"ব্যাংকের কর্মী পরিচয় দিয়ে একজন ফোনে আসা যাচাই কোড চাইছেন।"},"choices":[{"text":{"en":"Read the code aloud.","bn":"কোড বলে দিই।"},"safe":false,"feedback":{"en":"A verification code is private even if the caller claims authority.","bn":"প্রভাবশালী পরিচয় দিলেও যাচাই কোড গোপন রাখুন।"},"id":1061},{"text":{"en":"Send a screenshot of the code.","bn":"কোডের ছবি পাঠাই।"},"safe":false,"feedback":{"en":"A verification code is private even if the caller claims authority.","bn":"প্রভাবশালী পরিচয় দিলেও যাচাই কোড গোপন রাখুন।"},"id":1062},{"text":{"en":"Refuse and contact my bank independently.","bn":"না বলে নিজে ব্যাংকের সঙ্গে যোগাযোগ করি।"},"safe":true,"feedback":{"en":"A verification code is private even if the caller claims authority.","bn":"প্রভাবশালী পরিচয় দিলেও যাচাই কোড গোপন রাখুন।"},"id":1063}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (107, 'post', '{"id":107,"phase":"post","category":"suspicious","title":{"en":"Gift processing fee","bn":"উপহারের প্রক্রিয়াকরণ ফি"},"message":{"en":"A message promises a free appliance if you first pay a processing fee.","bn":"মেসেজে বলা হয়েছে আগে ফি দিলে বিনা মূল্যে যন্ত্র পাবেন।"},"choices":[{"text":{"en":"Send my card details.","bn":"কার্ডের তথ্য পাঠাই।"},"safe":false,"feedback":{"en":"Free gifts requiring unexpected fees may be fraudulent.","bn":"বিনা মূল্যের উপহারের জন্য অপ্রত্যাশিত ফি প্রতারণা হতে পারে।"},"id":1071},{"text":{"en":"Verify the offer through official channels without paying.","bn":"টাকা না দিয়ে অফিসিয়াল মাধ্যমে যাচাই করি।"},"safe":true,"feedback":{"en":"Free gifts requiring unexpected fees may be fraudulent.","bn":"বিনা মূল্যের উপহারের জন্য অপ্রত্যাশিত ফি প্রতারণা হতে পারে।"},"id":1072},{"text":{"en":"Pay the fee.","bn":"ফি দিই।"},"safe":false,"feedback":{"en":"Free gifts requiring unexpected fees may be fraudulent.","bn":"বিনা মূল্যের উপহারের জন্য অপ্রত্যাশিত ফি প্রতারণা হতে পারে।"},"id":1073}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (108, 'post', '{"id":108,"phase":"post","category":"suspicious","title":{"en":"Wallet link","bn":"ওয়ালেটের লিংক"},"message":{"en":"An unexpected message says your wallet will be frozen unless you update it using a link.","bn":"অপ্রত্যাশিত মেসেজে বলা হয়েছে লিংক দিয়ে আপডেট না করলে ওয়ালেট বন্ধ হবে।"},"choices":[{"text":{"en":"Open the official wallet app myself.","bn":"নিজে অফিসিয়াল ওয়ালেট অ্যাপ খুলি।"},"safe":true,"feedback":{"en":"Urgent account threats do not make unfamiliar links trustworthy.","bn":"জরুরি অ্যাকাউন্ট বন্ধের হুমকিতে অপরিচিত লিংক বিশ্বাসযোগ্য হয় না।"},"id":1081},{"text":{"en":"Follow the supplied link.","bn":"দেওয়া লিংক ব্যবহার করি।"},"safe":false,"feedback":{"en":"Urgent account threats do not make unfamiliar links trustworthy.","bn":"জরুরি অ্যাকাউন্ট বন্ধের হুমকিতে অপরিচিত লিংক বিশ্বাসযোগ্য হয় না।"},"id":1082},{"text":{"en":"Reply with my wallet PIN.","bn":"উত্তরে পিন দিই।"},"safe":false,"feedback":{"en":"Urgent account threats do not make unfamiliar links trustworthy.","bn":"জরুরি অ্যাকাউন্ট বন্ধের হুমকিতে অপরিচিত লিংক বিশ্বাসযোগ্য হয় না।"},"id":1083}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (109, 'post', '{"id":109,"phase":"post","category":"benign","title":{"en":"Expected reminder","bn":"প্রত্যাশিত স্মরণবার্তা"},"message":{"en":"Your known friend reminds you of the lunch you arranged together.","bn":"পরিচিত বন্ধু একসঙ্গে ঠিক করা দুপুরের খাবারের কথা মনে করিয়ে দিয়েছেন।"},"choices":[{"text":{"en":"Send my banking password.","bn":"ব্যাংকিং পাসওয়ার্ড পাঠাই।"},"safe":false,"feedback":{"en":"Ordinary expected communication is not automatically a scam.","bn":"সাধারণ প্রত্যাশিত যোগাযোগ নিজে থেকেই প্রতারণা নয়।"},"id":1091},{"text":{"en":"Report it only because it is a message.","bn":"শুধু মেসেজ বলে রিপোর্ট করি।"},"safe":false,"feedback":{"en":"Ordinary expected communication is not automatically a scam.","bn":"সাধারণ প্রত্যাশিত যোগাযোগ নিজে থেকেই প্রতারণা নয়।"},"id":1092},{"text":{"en":"Reply normally.","bn":"স্বাভাবিকভাবে উত্তর দিই।"},"safe":true,"feedback":{"en":"Ordinary expected communication is not automatically a scam.","bn":"সাধারণ প্রত্যাশিত যোগাযোগ নিজে থেকেই প্রতারণা নয়।"},"id":1093}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
INSERT INTO cb_scenario_seed (scenario_id, phase, payload) VALUES (110, 'post', '{"id":110,"phase":"post","category":"suspicious","title":{"en":"Urgent family payment","bn":"পরিবারের জরুরি টাকা"},"message":{"en":"An unfamiliar account claims to be your niece and urgently asks you to pay a bill.","bn":"অপরিচিত অ্যাকাউন্ট থেকে ভাগনি পরিচয় দিয়ে জরুরি বিল দিতে বলছে।"},"choices":[{"text":{"en":"Send my card number.","bn":"কার্ড নম্বর পাঠাই।"},"safe":false,"feedback":{"en":"Confirm identity independently before making payments.","bn":"টাকা দেওয়ার আগে নিজে পরিচয় যাচাই করুন।"},"id":1101},{"text":{"en":"Call my niece using her saved number.","bn":"ভাগনির সংরক্ষিত নম্বরে কল করি।"},"safe":true,"feedback":{"en":"Confirm identity independently before making payments.","bn":"টাকা দেওয়ার আগে নিজে পরিচয় যাচাই করুন।"},"id":1102},{"text":{"en":"Pay the bill immediately.","bn":"এখনই বিল দিই।"},"safe":false,"feedback":{"en":"Confirm identity independently before making payments.","bn":"টাকা দেওয়ার আগে নিজে পরিচয় যাচাই করুন।"},"id":1103}],"source":{"type":"author_created","original_label":null,"locator":"held-out assessment item"}}');
